  function collide(x,y){const m=maps[state.scene];if(x<0||y<0||x>=m.w||y>=m.h)return true;return m.blocks.some(([bx,by,bw,bh])=>x>=bx&&x<bx+bw&&y>=by&&y<by+bh)||activeNpcs().some(n=>n.x===x&&n.y===y);}
