  function changeScene(scene,x,y){state.scene=scene;state.x=x;state.y=y;state.walkFrame=0;showLabel(scene==='bulbo'?'MAISON DE '+state.playerName.toUpperCase():maps[scene].name);if(scene==='village')setObjective(state.flags.metMritto?'Explorer Bitch City ou prendre la Route 28 au nord':'Rendre visite à Mritto et Fratmentali');if(scene==='route28')setObjective('Remonter la Route 28 vers Talentia');if(scene==='beach')setObjective('Profiter de la plage de Bitch City');if(scene==='westField'||scene==='eastField')setObjective('Explorer cette future extension de Bitch City');draw();}
