  function showLine(){const [speaker,text]=state.dialogue.lines[state.dialogue.i];UI.speaker.textContent=speaker==='Bulbo'?state.playerName:speaker;UI.text.textContent=text.replaceAll('Bulbo',state.playerName).replaceAll('Nocturnyx','Dantonlix');const portrait={mritto:'assets/portrait-mritto-v1.jpg',frat:'assets/portrait-frat-v1.jpg',nicki:'assets/portrait-nicky-v1.png'}[state.dialogue.n.kind];UI.portrait.style.background=portrait?`center 16% / cover url("${portrait}")`:portraitColor(state.dialogue.n.kind);UI.dialogue.hidden=false;UI.prompt.classList.remove('show')}
  function advanceDialogue(){const d=state.dialogue;if(d.i<d.lines.length-1){d.i++;showLine();return}if(d.n.action==='mrittoGift'&&!state.flags.metMritto){state.flags.metMritto=true;state.balls=10;UI.balls.textContent='10';UI.plural.textContent='s';setObjective('Récupérer la carte auprès de Fratmentali')}if(d.n.action==='mapGift'&&!state.flags.gotMap){state.flags.gotMap=true;state.items.worldMap=true;UI.mapButton.hidden=false;setObjective('Prendre la sortie nord vers la Route 28')}if(d.n.action==='nickiHeal'){if(state.flags.metNicki)state.team.forEach(s=>s.hp=s.maxHp);else state.flags.metNicki=true}if(d.n.action==='jason'&&!state.flags.metJason){state.flags.metJason=true;state.relations.jason=1}else if(d.n.action==='jason'&&!state.flags.gotCream){state.flags.gotCream=true;state.items.dayCream=1;state.relations.jason=2;UI.cream.hidden=false;UI.creamCount.textContent='1'}const after=d.after;state.dialogue=null;UI.dialogue.hidden=true;draw();if(after)after()}

