  function startBattle(trainer){const enemy=trainer==='mritto'?{name:'Dantonlix',level:11,hp:72,maxHp:72,defense:47,trainer:'Mritto',icon:'☾',charmed:false}:{name:'Veloursa',level:11,hp:66,maxHp:66,defense:43,trainer:'Fratmentali',icon:'✦',charmed:false};state.battle={enemy,trainer,turnLocked:false,captureBonus:1};UI.enemySprite.textContent='';UI.enemySprite.className='battle-slay '+(trainer==='mritto'?'dantonlix':'veloursa')+' normal';UI.playerSprite.className='battle-slay sexy normal';UI.battle.classList.toggle('indoors',state.scene==='duo'||state.scene==='bulbo'||state.scene==='slayhouse');UI.battle.classList.toggle('theater',state.scene==='slayhouse');UI.battle.hidden=false;UI.battleText.textContent=enemy.trainer+' envoie '+enemy.name+' !';updateBattle()}
